llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "Isoniazid, a small polar pyridine hydrazide, showed 78% oral bioavailability in fed patients; its high transfer score and shared small polar heteroaromatic character support high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Piritrexim, a fused heteroaromatic diaminopyrimidine antifolate, showed approximately 75% oral bioavailability in patients; despite its larger size, its heteroaromatic/amino scaffold and oral absorption support high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Bromfenac, a small polar amino aryl-acetic acid, had 67% absolute oral bioavailability in healthy fasted subjects; high transferability and small polar drug character support high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "CP-409,092, an indole-containing amide, showed 69% bioavailability relative to IV in humans; the indole-like heteroaromatic core is relevant to the query's pyrrolopyrimidine and supports high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Naratriptan, an indole sulfonamide, had 74% oral bioavailability in women; high transferability and indole/polar heteroaromatic features support high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Vatalanib, a heteroaromatic drug containing a pyridylmethyl motif, had 58% absolute oral bioavailability in humans; the shared pyridylmethyl and heteroaromatic features support high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Nilotinib had 31% absolute oral bioavailability in fasted humans; although lower than other analogues, it remains above the 20% threshold and supports the high classification, with lower transferability due to its larger lipophilic structure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer human oral bioavailability measurements for small polar heteroaromatic drugs (isoniazid, piritrexim, bromfenac, CP-409,092, naratriptan, vatalanib) are all ≥31%, mostly 58-78%, supporting F≥20% for the query. The query's low molecular weight, good solubility, and neutral character are consistent with adequate absorption, and no affirmative low-F evidence with meaningful transferability was found.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the exact pyrrolo[2,3-d]pyrimidine query molecule.",
    "First-pass metabolism and transporter efflux liabilities were not directly assessed for the query.",
    "Melatonin low-F data have negligible transfer score and were not used as material evidence.",
    "Some records are relative bioavailability or formulation comparisons rather than absolute F measurements."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

